# Surah An-Nahl (chapter 16) — part 12: ayat 111-120 (IDs 2012-2021)
SURAH = 16

ENTRIES = {
2012: (
"اس دن ہر نفس آئے گا اپنی ذات کی وکالت کرتی ہوئی — اور ہر نفس کو اس کے عمل کا بدلہ دیا جائے گا اور ان پر کوئی ظلم نہیں کیا جائے گا",
"""۱۔ قیامت میں ہر نفس اپنے حمایتی ہو گا؛ ہر عمل کا بدلہ؛ انصاف کامل ہے۔
۲۔ ’’يَوْمَ تَأْتِي كُلُّ نَفْسٍ تُجَادِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ‘‘ — اس دن ہر نفس آئے گا اپنی ذات کی وکالت کرتی ہوئی — اور ہر نفس کو اس کے عمل کا بدلہ دیا جائے گا اور ان پر کوئی ظلم نہیں کیا جائے گا — یعنی جس دن ہر نفس اپنی ذات کی وکالت کرتی ہوئی آئے گا — اور ہر نفس کو اس کا عمل ادا دیا جائے گا اور ان پر کوئی ظلم نہیں کیا جائے گا۔
۳۔ عملی سبق: قیامت کے دن آپ خود اپنے وکیل ہوں گے؛ ابھی عملِ صالح جمع کرو۔"""
),
2013: (
"اور اللہ نے ایک بستی کی مثال بیان کی جو پرامن اور مطمئن تھی — اس کا رزق ہر طرف سے وافر آتا تھا — پھر اس نے اللہ کی نعمتوں کی ناشکری کی — پس اللہ نے اسے بھوک اور خوف کے لباس کا مزہ چکھایا اس کی بنا پر جو وہ کیا کرتی تھی",
"""۱۔ آسودہ بستی کی ناشکری کا انجام — بھوک و خوف؛ اللہ کی نعمتیں ہر وقت نہیں رہتیں۔
۲۔ ’’وَضَرَبَ اللَّهُ مَثَلًا قَرْيَۃً كَانَتْ آمِنَۃً مُّطْمَئِنَّۃً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ اللَّهِ فَأَذَاقَهَا اللَّهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ بِمَا كَانُوا يَصْنَعُونَ‘‘ — اور اللہ نے ایک بستی کی مثال بیان کی جو پرامن اور مطمئن تھی — اس کا رزق ہر طرف سے وافر آتا تھا — پھر اس نے اللہ کی نعمتوں کی ناشکری کی — پس اللہ نے اسے بھوک اور خوف کے لباس کا مزہ چکھایا اس کی بنا پر جو وہ کیا کرتی تھی — یعنی اللہ نے مثال بیان کی ایک بستی کی جو پرامن و مطمئن تھی اور اس کا رزق ہر طرف سے وافر آتا تھا — پھر اس نے اللہ کی نعمتوں کی ناشکری کی — پس اللہ نے اسے بھوک اور خوف کا لباس پہنایا ان کے اعمال کی بنا پر۔
۳۔ عملی سبق: نعمت کی ناشکری کا انجام بدبختی ہے؛ ہر وقت اللہ کا شکر کرو۔"""
),
2014: (
"اور یقیناً ان کے پاس ان ہی میں سے ایک رسول آیا — پس ان کی اس کو جھٹلایا — پس انہیں عذاب نے آ لیا اور وہ ظالم تھے",
"""۱۔ رسولانہ ندا ان تک پہنچی؛ انکار کیا؛ انجام عذاب؛ ظلم ان کی پوری خطا تھی۔
۲۔ ’’وَلَقَدْ جَاءَهُمْ رَسُولٌ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ الْعَذَابُ وَهُمْ ظَالِمُونَ‘‘ — اور یقیناً ان کے پاس ان ہی میں سے ایک رسول آیا — پس ان کی اس کو جھٹلایا — پس انہیں عذاب نے آ لیا اور وہ ظالم تھے — یعنی ان کے پاس ان ہی میں سے ایک رسول آیا — پس انہوں نے اس کو جھٹلایا — پس انہیں عذاب نے آ لیا اور وہ ظالم تھے۔
۳۔ عملی سبق: رسول کے انکار کا انجام تباہی ہے؛ نبیؐ پر ایمان لاؤ۔"""
),
2015: (
"پس اس میں سے کھاؤ جو اللہ نے تمہیں حلال اور پاک عطا کیا — اور اللہ کی نعمت کا شکر کرو اگر تم اسی کی عبادت کرتے ہو",
"""۱۔ اللہ کی حلال پاک روزی کھاؤ؛ شکر کرو؛ نعمت کا شکر عبادت کا حصہ ہے۔
۲۔ ’’فَكُلُوا مِمَّا رَزَقَكُمُ اللَّهُ حَلَالًا طَيِّبًا وَاشْكُرُوا نِعْمَتَ اللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ‘‘ —پس اس میں سے کھاؤ جو اللہ نے تمہیں حلال اور پاک عطا کیا — اور اللہ کی نعمت کا شکر کرو اگر تم اسی کی عبادت کرتے ہو۔
۳۔ عملی سبق: حلال کھاؤ؛ شکر کرو؛ اللہ کی نعمتوں میں اسراف نہ کرو۔"""
),
2016: (
"وہ صرف تمہارے اوپر حرام کیا ہے مُردار اور خون اور سور کا گوشت اور وہ چیز جو غیر اللہ کے نام پر ذبح کی گئی ہو — پس جو مجبور ہو جائے بغیر سرکشی اور زیادتی کے تو بے شک اللہ بخشنے والا رحیم ہے",
"""۱۔ چار حرام چیزیں: مُردار، خون، خنزیر کا گوشت، غیر اللہ کے نام ذبح — اضطرار کی حالت میں جائز۔
۲۔ ’’إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَۃَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ‘‘ — وہ صرف تمہارے اوپر حرام کیا ہے مُردار اور خون اور سور کا گوشت اور وہ چیز جو غیر اللہ کے نام پر ذبح کی گئی ہو — پس جو مجبور ہو جائے بغیر سرکشی اور زیادتی کے تو بے شک اللہ بخشنے والا رحیم ہے — یعنی اللہ نے تم پر صرف مُردار اور خون اور سور کا گوشت اور غیر اللہ کے نام پر ذبح کی گئی چیز حرام کی ہے — پس جو مجبور ہو جائے بغیر سرکشی اور زیادتی کے تو بے شک اللہ بخشنے والا رحیم ہے۔
۳۔ عملی سبق: حلال و حرام کی حدود کا احترام کریں؛ اضطرار میں اللہ کی گنجائش ہے؛ اسراف نہیں۔"""
),
2017: (
"اور جو تمہاری زبانیں جھوٹ وصف کرتی ہیں اس پر یہ نہ کہو کہ یہ حلال ہے اور یہ حرام ہے تاکہ اللہ پر جھوٹ گھڑو — بے شک وہ لوگ جو اللہ پر جھوٹ گھڑتے ہیں وہ کامیاب نہیں ہوتے",
"""۱۔ اپنی بات کو اللہ کا فیصلہ نہ کہو؛ یہ افتراء ہے؛ جھوٹے لوگ کامیاب نہیں ہوتے۔
۲۔ ’’وَلَا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ هَٰذَا حَلَالٌ وَهَٰذَا حَرَامٌ لِّتَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ‘‘ — اور جو تمہاری زبانیں جھوٹ وصف کرتی ہیں اس پر یہ نہ کہو کہ یہ حلال ہے اور یہ حرام ہے تاکہ اللہ پر جھوٹ گھڑو — بے شک وہ لوگ جو اللہ پر جھوٹ گھڑتے ہیں وہ کامیاب نہیں ہوتے — یعنی جو تمہاری زبانیں جھوٹ وصف کرتی ہیں اس پر یہ نہ کہو کہ یہ حلال ہے اور یہ حرام ہے — تاکہ اللہ پر جھوٹ گھڑو — بے شک جو اللہ پر جھوٹ گھڑتے ہیں وہ کامیاب نہیں ہوتے۔
۳۔ عملی سبق: اللہ پر جھوٹ گھڑنا سب سے بڑا گناہ ہے؛ اپنی رائے کو اللہ کا حکم نہ بنائیں۔"""
),
2018: (
"دنیا میں تھوڑی سی زندگی کی چیز ہے— اور ان کے لیے دردناک عذاب ہے",
"""۱۔ دنیاوی فائدے عارضی ہیں؛ آخرت کا انعام یا عذاب ہمیشہ رہنے والا ہے۔
۲۔ ’’مَتَاعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ‘‘ — دنیا میں تھوڑی سی زندگی کی چیز ہے— اور ان کے لیے دردناک عذاب ہے — یعنی دنیا میں تھوڑی سی زندگی کی چیز ہے — اور ان کے لیے دردناک عذاب ہے۔
۳۔ عملی سبق: دنیا کی لذتیں ختم ہو جاتی ہیں؛ آخرت کی زندگی دائمی ہے؛ اس کے لیے عمل کرو۔"""
),
2019: (
"اور یہود پر ہم نے ان چیزوں کو حرام کیا جن کا بیان ہم نے تمہیں پہلے کر دیا — اور ہم نے ان پر کوئی ظلم نہیں کیا بلکہ وہ خود اپنے نفسوں پر ظلم کرتے تھے",
"""۱۔ یہود پر پابندیاں ان کی نافرمانی کی سزا تھیں؛ اللہ کبھی ظالم نہیں۔
۲۔ ’’وَعَلَى الَّذِينَ هَادُوا حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ وَمَا ظَلَمْنَاهُمْ وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ‘‘ — اور یہود پر ہم نے ان چیزوں کو حرام کیا جن کا بیان ہم نے تمہیں پہلے کر دیا — اور ہم نے ان پر کوئی ظلم نہیں کیا بلکہ وہ خود اپنے نفسوں پر ظلم کرتے تھے — یعنی یہود پر ہم نے ان چیزوں کو حرام کیا جن کا بیان تمہیں پہلے کر دیا — اور ہم نے ان پر ظلم نہیں کیا بلکہ وہ خود اپنے نفسوں پر ظلم کرتے تھے۔
۳۔ عملی سبق: اللہ کبھی ظلم نہیں کرتا؛ نافرمانی کی سزا خود انسان بھگتتا ہے۔"""
),
2020: (
"پھر بے شک آپ کا رب ان لوگوں کے لیے جو جہالت سے برا عمل کریں پھر اس کے بعد توبہ کریں اور اصلاح کریں — بے شک آپ کا رب اس کے بعد بخشنے والا رحیم ہے",
"""۱۔ نادانی میں گناہ کرے پھر توبہ و اصلاح کرے — اللہ بخشتا ہے؛ توحید کا پیغام۔
۲۔ ’’ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا السُّوءَ بِجَهَالَۃٍ ثُمَّ تَابُوا مِن بَعْدِ ذَٰلِكَ وَأَصْلَحُوا إِنَّ رَبَّكَ مِن بَعْدَهَا لَغَفُورٌ رَّحِيمٌ‘‘ — پھر بے شک آپ کا رب ان لوگوں کے لیے جو جہالت سے برا عمل کریں پھر اس کے بعد توبہ کریں اور اصلاح کریں — بے شک آپ کا رب اس کے بعد بخشنے والا رحیم ہے — یعنی آپ کا رب ان لوگوں کے لیے ہے جو جہالت سے برا عمل کریں پھر توبہ کریں اور اصلاح کریں — آپ کا رب اس کے بعد بخشنے والا رحیم ہے۔
۳۔ عملی سبق: اللہ سے توبہ کا دروازہ ہمیشہ کھلا ہے؛ سچی توبہ اور اصلاح کے بعد بخشش۔"""
),
2021: (
"بے شک ابراہیمؑ اللہ کے لیے ایک کامل امت تھے — فرمانبردار — یکسو — اور وہ مشرکوں میں سے نہیں تھے",
"""۱۔ حضرت ابراہیمؑ ایک لشکر تھے؛ خالص توحید؛ تمام نیکیوں کی جامع شخصیت؛ مشرکین سے الگ۔
۲۔ ’’إِنَّ إِبْرَاهِيمَ كَانَ أُمَّۃً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ‘‘ —بے شک ابراہیمؑ اللہ کے لیے ایک کامل امت تھے — فرمانبردار — یکسو — اور وہ مشرکوں میں سے نہیں تھے۔
۳۔ عملی سبق: ابراہیمؑ کی طرح زندگی گزارو؛ توحید اور اطاعت اختیار کرو؛ شرک سے دور رہو۔"""
),
}
